#include <stdio.h>

int main(void) {
    int V, A, F, P;
    if (scanf("%d %d %d %d", &V, &A, &F, &P) != 4) return 0;

    int contas[3] = {A, F, P};

    for (int i = 0; i < 2; i++) {
        for (int j = i + 1; j < 3; j++) {
            if (contas[i] > contas[j]) {
                int temp = contas[i];
                contas[i] = contas[j];
                contas[j] = temp;
            }
        }
    }

    int pagas = 0;
    for (int i = 0; i < 3; i++) {
        if (V >= contas[i]) {
            V -= contas[i];
            pagas++;
        } else {
            break;
        }
    }

    printf("%d\n", pagas);
    return 0;
}
```

